<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Access\Tenant\Domain\TenantRef;
use Civi\Lughauth\Features\Access\ConsentPurpose\Domain\ConsentPurposeKeyOptions;
use PHPUnit\Framework\TestCase;
use Civi\Lughauth\Features\Access\ConsentPurpose\Domain\ConsentPurpose;

final class ConsentPurposeUnitTest extends TestCase
{
    public function test_init_store_values(): void
    {
        // @Arrange
        $one = new ConsentPurpose(
            uid: 'one',
            tenant: new TenantRef('one'),
            key: ConsentPurposeKeyOptions::MARKETING,
            title: 'one',
            description: 'one',
            required: true,
            activationDate: (new \DateTimeImmutable('1980-08-20T14:32:45.123Z')),
            version: 1,
        );

        // @Act
        $other = $one->toAttributes()->createNewInstance();
        $calculated = ConsentPurpose::calculatedFields();

        // @Assert
        $this->assertEquals([], $calculated);
        $this->assertEquals($one->uid(), $other->uid());
        $this->assertEquals($one->getTenant(), $other->getTenant());
        $this->assertTrue($one->isTenantChanged());
        $this->assertEquals($one->getKey(), $other->getKey());
        $this->assertTrue($one->isKeyChanged());
        $this->assertEquals($one->getTitle(), $other->getTitle());
        $this->assertTrue($one->isTitleChanged());
        $this->assertEquals($one->getDescription(), $other->getDescription());
        $this->assertTrue($one->isDescriptionChanged());
        $this->assertEquals($one->isRequired(), $other->isRequired());
        $this->assertTrue($one->isRequiredChanged());
        $this->assertEquals($one->getActivationDate(), $other->getActivationDate());
        $this->assertTrue($one->isActivationDateChanged());
        $this->assertEquals($one->getVersion(), $other->getVersion());
        $this->assertTrue($one->isVersionChanged());
    }
    public function test_replace_change_values(): void
    {
        // @Arrange
        $base = new ConsentPurpose(
            uid: 'one',
            tenant: new TenantRef('one'),
            key: ConsentPurposeKeyOptions::MARKETING,
            title: 'one',
            description: 'one',
            required: true,
            activationDate: (new \DateTimeImmutable('1980-08-20T14:32:45.123Z')),
            version: 1,
        );
        $other = new ConsentPurpose(
            uid: 'other',
            tenant: new TenantRef('other'),
            key: ConsentPurposeKeyOptions::ANALYTICS,
            title: 'other',
            description: 'other',
            required: false,
            activationDate: (new \DateTimeImmutable('1981-09-06T14:32:45.123Z')),
            version: 2,
        );

        // @Act
        $one = $base->replace($other->toAttributes());

        // @Assert
        $this->assertEquals($one->uid(), $base->uid());
        $this->assertEquals($one->getTenant(), $other->getTenant());
        $this->assertTrue($one->isTenantChanged($base));
        $this->assertEquals($one->getKey(), $other->getKey());
        $this->assertTrue($one->isKeyChanged($base));
        $this->assertEquals($one->getTitle(), $other->getTitle());
        $this->assertTrue($one->isTitleChanged($base));
        $this->assertEquals($one->getDescription(), $other->getDescription());
        $this->assertTrue($one->isDescriptionChanged($base));
        $this->assertEquals($one->isRequired(), $other->isRequired());
        $this->assertTrue($one->isRequiredChanged($base));
        $this->assertEquals($one->getActivationDate(), $other->getActivationDate());
        $this->assertTrue($one->isActivationDateChanged($base));
        $this->assertEquals($one->getVersion(), $other->getVersion());
        $this->assertTrue($one->isVersionChanged($base));
    }
    public function test_json_compare(): void
    {
        // @Arrange
        $one = new ConsentPurpose(
            uid: 'one',
            tenant: new TenantRef('one'),
            key: ConsentPurposeKeyOptions::MARKETING,
            title: 'one',
            description: 'one',
            required: true,
            activationDate: (new \DateTimeImmutable('1980-08-20T14:32:45.123Z')),
            version: 1,
        );

        // @Act
        $json = $one->asPublicJson();

        // @Assert
        $this->assertEquals('one', $json['uid']);
        $this->assertEquals('one', $json['tenant']['$ref']);
        $this->assertEquals(ConsentPurposeKeyOptions::MARKETING, $json['key']);
        $this->assertEquals('one', $json['title']);
        $this->assertEquals(true, $json['required']);
        $this->assertEquals((new \DateTimeImmutable('1980-08-20T14:32:45.123Z')), $json['activationDate']);
        $this->assertEquals(1, $json['version']);
    }
